_CALLS = 0

def _value(obj, key, default=None):
    if isinstance(obj, dict):
        return obj.get(key, default)
    getter = getattr(obj, "get", None)
    if callable(getter):
        return getter(key, default)
    return getattr(obj, key, default)

def agent(observation, configuration=None):
    del configuration
    global _CALLS
    raw_step = _value(observation, "step", None)
    try:
        step = int(raw_step) if raw_step is not None else _CALLS
    except (TypeError, ValueError):
        step = _CALLS
    _CALLS += 1
    step = max(0, min(step, 718))
    if step < 72:
        return copy.deepcopy(_DATA["opening"][step])
    town = _value(observation, "town", {})
    shops = _value(town, "unlocked_shops", []) or []
    route = None
    for count in range(1, min(len(shops), 8) + 1):
        if step < 72 * count:
            break
        candidate = _DATA["route_map"].get("|".join(shops[:count]))
        if candidate is not None:
            route = candidate
    if route is None:
        route = next(iter(_DATA["routes"]))
    return copy.deepcopy(_DATA["routes"][str(route)][step])

def kaggle_shunki_later_lookup_entrypoint(observation, configuration=None):
    return agent(observation, configuration)


# Complete ICE/BRUNCH schedule replacement. The routes share all actions
# through turn 240; every affected map transition was checked at build time.
for _ice_schedule_key, _ice_schedule_source in list(_DATA["route_map"].items()):
    if _ice_schedule_source == 113445495:
        _DATA["route_map"][_ice_schedule_key] = 113383763
del _ice_schedule_key, _ice_schedule_source

def kaggle_shunki_ice_schedule_entrypoint(observation, configuration=None):
    return agent(observation, configuration)


